// Busca la primera solicitud PENDIENTE. Si no hay, el flujo se detiene aquí.
const fx = v => (typeof v === 'number' && v > 20000)
  ? new Date(Math.round((v - 25569) * 86400000)).toISOString().slice(0, 19).replace('T', ' ')
  : (v ?? '');
const filas = $input.all().map(i => ({ ...i.json, fecha_solicitud: fx(i.json.fecha_solicitud), fecha_fin: fx(i.json.fecha_fin) }));
const idx = filas.findIndex(f => String(f.estado).trim().toUpperCase() === 'PENDIENTE');
if (idx === -1) return [];
filas[idx].estado = 'EN_PROCESO';
return filas.map(json => ({ json }));

// Convierte los pares de la zona gris en lotes de texto compacto para el agente.
const TAM_LOTE = 10;
const raw = $input.first().json;
const pares = Array.isArray(raw.data) ? raw.data : [];
if (pares.length === 0) return [{ json: { lote: 0, n_pares: 0, pares_texto: 'SIN_PARES' } }];

const d10 = v => String(v ?? '').slice(0, 10);
const edad = (nac, ref) => {
  if (!nac || !ref) return '?';
  const a = new Date(nac), b = new Date(ref);
  if (isNaN(a) || isNaN(b)) return '?';
  let e = b.getFullYear() - a.getFullYear();
  if (b.getMonth() < a.getMonth() || (b.getMonth() === a.getMonth() && b.getDate() < a.getDate())) e--;
  return e;
};
const fmt = r => [
  r.tipo_documento, r.numero_documento,
  [r.primer_nombre, r.segundo_nombre, r.primer_apellido, r.segundo_apellido].filter(Boolean).join(' '),
  'nac ' + (d10(r.fecha_nacimiento) || 'SIN DATO'),
  'registro ' + d10(r.fecha_registro) + ' (edad al registrarse: ' + edad(r.fecha_nacimiento, r.fecha_registro) + ')',
  'tel ' + (r.telefono ?? ''), r.correo ?? '', r.direccion ?? '', r.ciudad ?? '',
].join(' | ');
const sn = v => (v ? 'sí' : 'no');
const describir = (p, k) => {
  const f = p.caracteristicas;
  const doc = f.doc === 1 ? 'igual' : f.doc === 0.8 ? 'difiere en un dígito' : 'distinto';
  return `PAR ${k + 1} (id_a=${p.id_a}, id_b=${p.id_b}) score_modelo=${p.score}\n` +
    `A: ${fmt(p.registro_a)}\nB: ${fmt(p.registro_b)}\n` +
    `Señales: documento ${doc}; fecha de nacimiento: ${f.fecha_faltante ? 'falta en un registro' : f.fecha_igual ? 'igual' : 'distinta'}; similitud de nombre ${f.sim_nombre}; ` +
    `mismo teléfono: ${sn(f.tel_igual)}; mismo correo: ${sn(f.correo_igual)}; uno TI y otro CC: ${sn(f.ti_cc)}`;
};
const lotes = [];
for (let i = 0; i < pares.length; i += TAM_LOTE) {
  const g = pares.slice(i, i + TAM_LOTE);
  lotes.push({ json: {
    lote: lotes.length + 1, n_pares: g.length,
    pares_texto: `Evalúa estos ${g.length} pares:\n\n` + g.map((p, j) => describir(p, i + j)).join('\n\n') +
      `\n\nDevuelve exactamente ${g.length} decisiones, una por cada PAR de arriba, sin omitir ninguno.`,
  } });
}
return lotes;

// Une las decisiones de todos los lotes. Busca en cualquier estructura de salida
// (objeto, lista o texto con JSON) porque el agente no siempre la anida igual.
const esDecision = v => v && typeof v === 'object' && !Array.isArray(v) && 'id_a' in v && 'id_b' in v && 'decision' in v;
const buscar = (v, acc) => {
  if (v == null) return;
  if (typeof v === 'string') {
    const m = v.match(/[\[{][\s\S]*[\]}]/);
    if (m) { try { buscar(JSON.parse(m[0]), acc); } catch (e) { /* texto sin JSON válido */ } }
    return;
  }
  if (Array.isArray(v)) { v.forEach(x => buscar(x, acc)); return; }
  if (typeof v === 'object') {
    if (esDecision(v)) { acc.push(v); return; }
    Object.values(v).forEach(x => buscar(x, acc));
  }
};
const todas = [];
const porLote = [];
$input.all().forEach((it, k) => {
  const acc = [];
  buscar(it.json, acc);
  todas.push(...acc);
  porLote.push({ lote: k + 1, decisiones: acc.length, claves_salida: Object.keys(it.json) });
});
return [{ json: { decisiones: todas, diagnostico: porLote } }];

// Segundo intento: arma lotes solo con los pares que quedaron sin decisión válida.
const TAM_LOTE = 5;
const todos = $('Extraer zona gris').first().json.data ?? [];
const decididos = new Set(($input.first().json.decisiones ?? []).map(d => [d.id_a, d.id_b].sort((x, y) => x - y).join('-')));
const raw = { data: todos.filter(p => !decididos.has([p.id_a, p.id_b].sort((x, y) => x - y).join('-'))) };
const pares = Array.isArray(raw.data) ? raw.data : [];
if (pares.length === 0) return [{ json: { lote: 0, n_pares: 0, pares_texto: 'SIN_PARES' } }];

const d10 = v => String(v ?? '').slice(0, 10);
const edad = (nac, ref) => {
  if (!nac || !ref) return '?';
  const a = new Date(nac), b = new Date(ref);
  if (isNaN(a) || isNaN(b)) return '?';
  let e = b.getFullYear() - a.getFullYear();
  if (b.getMonth() < a.getMonth() || (b.getMonth() === a.getMonth() && b.getDate() < a.getDate())) e--;
  return e;
};
const fmt = r => [
  r.tipo_documento, r.numero_documento,
  [r.primer_nombre, r.segundo_nombre, r.primer_apellido, r.segundo_apellido].filter(Boolean).join(' '),
  'nac ' + (d10(r.fecha_nacimiento) || 'SIN DATO'),
  'registro ' + d10(r.fecha_registro) + ' (edad al registrarse: ' + edad(r.fecha_nacimiento, r.fecha_registro) + ')',
  'tel ' + (r.telefono ?? ''), r.correo ?? '', r.direccion ?? '', r.ciudad ?? '',
].join(' | ');
const sn = v => (v ? 'sí' : 'no');
const describir = (p, k) => {
  const f = p.caracteristicas;
  const doc = f.doc === 1 ? 'igual' : f.doc === 0.8 ? 'difiere en un dígito' : 'distinto';
  return `PAR ${k + 1} (id_a=${p.id_a}, id_b=${p.id_b}) score_modelo=${p.score}\n` +
    `A: ${fmt(p.registro_a)}\nB: ${fmt(p.registro_b)}\n` +
    `Señales: documento ${doc}; fecha de nacimiento: ${f.fecha_faltante ? 'falta en un registro' : f.fecha_igual ? 'igual' : 'distinta'}; similitud de nombre ${f.sim_nombre}; ` +
    `mismo teléfono: ${sn(f.tel_igual)}; mismo correo: ${sn(f.correo_igual)}; uno TI y otro CC: ${sn(f.ti_cc)}`;
};
const lotes = [];
for (let i = 0; i < pares.length; i += TAM_LOTE) {
  const g = pares.slice(i, i + TAM_LOTE);
  lotes.push({ json: {
    lote: lotes.length + 1, n_pares: g.length,
    pares_texto: `Evalúa estos ${g.length} pares:\n\n` + g.map((p, j) => describir(p, i + j)).join('\n\n') +
      `\n\nDevuelve exactamente ${g.length} decisiones, una por cada PAR de arriba, sin omitir ninguno.`,
  } });
}
return lotes;

// Une las decisiones del primer intento y del reintento (sin duplicar pares).
const esDecision = v => v && typeof v === 'object' && !Array.isArray(v) && 'id_a' in v && 'id_b' in v && 'decision' in v;
const buscar = (v, acc) => {
  if (v == null) return;
  if (typeof v === 'string') {
    const m = v.match(/[\[{][\s\S]*[\]}]/);
    if (m) { try { buscar(JSON.parse(m[0]), acc); } catch (e) {} }
    return;
  }
  if (Array.isArray(v)) { v.forEach(x => buscar(x, acc)); return; }
  if (typeof v === 'object') {
    if (esDecision(v)) { acc.push(v); return; }
    Object.values(v).forEach(x => buscar(x, acc));
  }
};
const primero = $('Juntar decisiones').first().json;
const nuevas = [];
$input.all().forEach(it => buscar(it.json, nuevas));
const clave = d => [d.id_a, d.id_b].map(Number).sort((x, y) => x - y).join('-');
const vistos = new Set(primero.decisiones.map(clave));
const agregadas = nuevas.filter(d => !vistos.has(clave(d)));
return [{ json: {
  decisiones: primero.decisiones.concat(agregadas),
  diagnostico: { primer_intento: primero.diagnostico, decisiones_reintento: agregadas.length },
} }];

const previas = $input.all().map(i => i.json)
  .filter(r => r.id_ejecucion !== undefined && r.id_ejecucion !== '');
const m = $('Leer métricas').first().json;
const ag = $('Leer métricas agente').first().json;
previas.push({
  id_ejecucion: m.id_ejecucion,
  fecha: m.fecha,
  registros_procesados: m.registros_procesados,
  pares_evaluados: m.pares_evaluados,
  duplicados_auto: m.duplicados_auto,
  duplicados_agente: ag.duplicados_agente,
  pendientes_revision: ag.revision_humana,
  duracion_seg: m.duracion_seg,
  version_modelo: m.version_modelo,
});
return previas.map(json => ({ json }));

const valida = r => r.id_origen !== undefined && r.id_origen !== '';
const previas = $input.all().map(i => i.json).filter(valida);
const nuevas = $('Extraer fusiones nuevas').all().map(i => i.json).filter(valida);
const filas = previas.concat(nuevas);
if (filas.length === 0) {
  return [{ json: { id_ejecucion: '', id_origen: '', id_maestro: '', score: '', decidido_por: '', justificacion: '' } }];
}
return filas.map(json => ({ json }));

const fx = v => (typeof v === 'number' && v > 20000)
  ? new Date(Math.round((v - 25569) * 86400000)).toISOString().slice(0, 19).replace('T', ' ')
  : (v ?? '');
const ahora = $now.toFormat('yyyy-MM-dd HH:mm:ss');
return $input.all().map(i => {
  const f = { ...i.json, fecha_solicitud: fx(i.json.fecha_solicitud), fecha_fin: fx(i.json.fecha_fin) };
  if (String(f.estado).trim().toUpperCase() === 'EN_PROCESO') {
    f.estado = 'COMPLETADO';
    f.fecha_fin = ahora;
  }
  return { json: f };
});

// Reúne las cifras de la ejecución para el informe (sin datos personales)
const m = $('Leer métricas').first().json;
const ag = $('Leer métricas agente').first().json;
const dec = $('Juntar decisiones finales').first().json.decisiones;
const historial = $('Agregar ejecución').all().map(i => i.json);
const previas = historial.slice(Math.max(0, historial.length - 6), historial.length - 1);
const conteo = dec.reduce((acc, d) => { acc[d.decision] = (acc[d.decision] || 0) + 1; return acc; }, {});
const confianzaMedia = dec.length ? (dec.reduce((s, d) => s + Number(d.confianza || 0), 0) / dec.length).toFixed(2) : 'n/a';
const ejemplos = dec.slice(0, 12).map(d => `- ${d.decision} (confianza ${d.confianza}): ${d.justificacion}`).join('\n');
const totales = {
  registros_procesados: m.registros_procesados,
  pares_evaluados: m.pares_evaluados,
  fusiones_modelo: m.duplicados_auto,
  pares_zona_gris: ag.pares_zona_gris,
  fusiones_agente: ag.duplicados_agente,
  total_fusiones: m.duplicados_auto + ag.duplicados_agente,
  descartados_por_agente_como_distintos: ag.distintos,
  revision_humana: ag.revision_humana,
  decisiones_invalidas: ag.decisiones_invalidas,
  duracion_modelo_seg: m.duracion_seg,
};
const contexto = [
  `Ejecución ${m.id_ejecucion} (${m.fecha})`,
  `Totales (usa estas cifras tal cual): ${JSON.stringify(totales)}`,
  `Parámetros: modelo ${m.version_modelo}, umbral alto ${m.umbral_alto}, umbral bajo ${m.umbral_bajo}, confianza mínima del agente ${ag.umbral_confianza}`,
  `Decisiones del agente por tipo: ${JSON.stringify(conteo)}; confianza media: ${confianzaMedia}`,
  `Ejemplos de justificaciones del agente:\n${ejemplos || '(no hubo pares en zona gris)'}`,
  `Ejecuciones anteriores (la más reciente al final): ${JSON.stringify(previas)}`,
].join('\n\n');
return [{ json: { contexto } }];

